package library;

import exceptions.BookAlreadyAvailableException;

/**
 * Represents a book in the library.
 *
 * id is auto-generated by a static counter; title/author/genre are final (immutable).
 * available is the mutable state, controlled through borrow()/returnBook().
 */
public class Book {

    private static int nextId = 1;

    private final int id;
    private final String title;
    private final String author;
    private final String genre;
    private boolean available;

    public Book(String title, String author, String genre, boolean available) {
        this.id = nextId++;
        this.title = title;
        this.author = author;
        this.genre = genre;
        this.available = available;
    }

    public int getId() {
        return id;
    }

    public String getTitle() {
        return title;
    }

    public String getAuthor() {
        return author;
    }

    public String getGenre() {
        return genre;
    }

    public boolean isAvailable() {
        return available;
    }

    // Marks the book as borrowed. Note: this one is "lenient" (prints a message
    // when already borrowed instead of throwing) — contrasted with returnBook().
    public void borrow() {
        if (available) {
            available = false;
            System.out.println("Book borrowed successfully.");
        } else {
            System.out.println("Book is already borrowed.");
        }
    }

    // Marks the book as available again. Throws a checked exception if the book
    // is already available — the caller must handle or declare it.
    public void returnBook() throws BookAlreadyAvailableException {
        if (available) {
            throw new BookAlreadyAvailableException(
                    "Book already available: " + title
            );
        }

        available = true;
        System.out.println("Book returned successfully.");
    }

    // Human-readable representation, used by the statistics output and printing.
    @Override
    public String toString() {
        return "Book{" +
                "id=" + id +
                ", title='" + title + '\'' +
                ", author='" + author + '\'' +
                ", genre='" + genre + '\'' +
                ", available=" + available +
                '}';
    }
}